def parse_minutes(text):
    numbers = []
    for word in text.split():
        numbers.append(int(word))
    return numbers

def last_minutes(items):
    if len(items) == 0:
        return None
    return items[-1]

minutes = parse_minutes(input())
last = last_minutes(minutes)
if last is None:
    print("暂无记录")
else:
    print(last)
